  selection:{strategy_authority:{value:'Owns regional technology strategy',status:'Confirmed',source:'CEO interview brief',observed:'26 Aug'},pnl:{value:'Owns technology operating budget; business P&L remains outside role',status:'Confirmed',source:'Recruiter + CHRO confirmation',observed:'24 Aug'},compensation:{value:'SGD 280k–330k base range',status:'Estimate',source:'Recruiter conversation',observed:'24 Aug',confidence:'Moderate'}},
