  offer:{strategy_authority:{value:'Owns regional technology strategy',status:'Confirmed',source:'Written offer brief',observed:'04 Sep'},pnl:{value:'Technology budget authority confirmed; no business-unit P&L',status:'Confirmed',source:'Written offer brief',observed:'04 Sep'},compensation:{value:'SGD 310k base · 30% target bonus · equity grant',status:'Confirmed',source:'Written offer',observed:'04 Sep'}}
