function applyStageAssertionSnapshot(stage){for(const [id,base] of Object.entries(assertionBaseline))assertions[id]=JSON.parse(JSON.stringify(base));for(const [id,patch] of Object.entries(stageAssertionOverlays[stage]||{}))Object.assign(assertions[id],patch);renderBriefing()}
function decisionText(o){if(o.id!=='opp_apac_vpt_01'||dispositions[o.id]!=='pursuing')return o.decision;if(workspaceStage==='precontact')return 'Likely step-up. The decision turns on strategy authority.';if(workspaceStage==='recruiter')return 'Likely step-up. Scope is promising; P&L and compensation remain provisional.';if(workspaceStage==='selection')return 'Strategy authority is now supported. Selection risk shifts to mandate confidence and industry adjacency.';if(workspaceStage==='final')return 'The role clears the authority threshold. Final decision now depends on leadership fit, references, and package.';return 'Authority and package are now known. The decision is whether the mandate and trade-offs justify the move.'}


