  precontact:{label:'Pre-contact',next:{title:'Confirm strategy ownership before asking Sarah for an introduction.',why:'The warm route is useful only if the role is worth network capital.',cta:'Prepare questions'},ready:[['Career evidence','3 relevant'],['Positioning brief','Not prepared'],['Resume variant','Not prepared']],activity:[['22 Aug','Reporting line confirmed: CEO'],['21 Aug','Role page captured'],['20 Aug','Recruiter note added']]},
