  precontact:[['Pre-contact','Current research and route planning','current'],['Recruiter conversation','Not started','future'],['Selection','Not started','future'],['Final / references','Not started','future'],['Offer','Not started','future']],
  recruiter:[['Pre-contact','Research complete enough to engage','done'],['Recruiter conversation','Current','current'],['Selection','Not started','future'],['Final / references','Not started','future'],['Offer','Not started','future']],
  selection:[['Pre-contact','Complete','done'],['Recruiter conversation','Complete','done'],['CEO interview','Next · 26 Aug','current'],['Final / references','Not started','future'],['Offer','Not started','future']],
  final:[['Pre-contact','Complete','done'],['Recruiter conversation','Complete','done'],['Selection','CEO round complete','done'],['Final / references','Current','current'],['Offer','Not started','future']],
