const dispositions=Object.fromEntries(opportunities.map(o=>[o.id,'discovered']));
let activeFilter='shortlist';
let selectedOpportunityId=opportunities[0].id;
let selectedEvidence=new Set();
let researchOpen=new Set();
let compareSelection=new Set();
let workspaceStage='precontact';
let workspaceSection='brief';
const stateLabel={discovered:'New',watching:'Saved',exploring:'Under review',pursuing:'Active',passed:'Closed',closed:'Closed'};
const byId=id=>opportunities.find(o=>o.id===id);

function log(type,detail={}){const e={t_ms:Math.round(performance.now()-startedAt),type,...detail};session.events.push(e);renderEvents()}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1500)}
function showView(name){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(`${name}View`).classList.add('active');const navName=name==='pursuit'?'opportunities':name;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===navName))}
function statusClass(status){return status.toLowerCase()==='confirmed'?'confirmed':status.toLowerCase()==='estimate'?'estimate':'open'}
function eventText(v){return typeof v==='function'?v():v}

function renderBriefing(){
  const groups=['Now','Due today','Tomorrow'];
  document.getElementById('briefingCount').textContent=briefingEvents.length;
  document.getElementById('briefingLedger').innerHTML=groups.map(group=>{
    const items=briefingEvents.filter(e=>e.group===group);
    return `<section class="ledger-group"><div class="ledger-group-head"><strong>${group}</strong><span>${items.length}</span></div>${items.map(e=>`<div class="ledger-event" data-event="${e.id}"><div class="event-time"><strong>${e.kind}</strong><span>${e.time}</span></div><div class="event-subject"><strong>${e.subject}</strong><span>${e.sub}</span></div><div class="event-change">${eventText(e.change)}</div><div class="event-context"><strong>${e.context}</strong><span>${e.detail}</span></div><button class="text-btn" data-event-open="${e.id}">${e.cta} →</button></div>`).join('')}</section>`;
  }).join('');
  document.querySelectorAll('[data-event-open]').forEach(btn=>btn.onclick=()=>{const e=briefingEvents.find(x=>x.id===btn.dataset.eventOpen);openOpportunity(e.target,`briefing:${e.id}`);log('briefing_event_opened',{event_id:e.id,target:e.target})});
}

function filterMatches(o){const s=dispositions[o.id];if(activeFilter==='all')return true;if(activeFilter==='shortlist')return o.shortlisted&&!['passed','closed'].includes(s);if(activeFilter==='saved')return s==='watching';if(activeFilter==='pursuing')return s==='pursuing';if(activeFilter==='closed')return ['passed','closed'].includes(s);return true}
function updateCounts(){const shortlist=opportunities.filter(o=>o.shortlisted&&!['passed','closed'].includes(dispositions[o.id])).length;document.getElementById('countShortlist').textContent=shortlist;document.getElementById('scanShortlistCount').textContent=shortlist;document.getElementById('countAll').textContent=opportunities.length;document.getElementById('countSaved').textContent=opportunities.filter(o=>dispositions[o.id]==='watching').length;document.getElementById('countPursuing').textContent=opportunities.filter(o=>dispositions[o.id]==='pursuing').length;document.getElementById('countClosed').textContent=opportunities.filter(o=>['passed','closed'].includes(dispositions[o.id])).length}
function renderOpportunityList(){
  const items=opportunities.filter(filterMatches);if(items.length&&!items.some(o=>o.id===selectedOpportunityId))selectedOpportunityId=items[0].id;
  document.getElementById('oppList').innerHTML=items.length?items.map(o=>`<div class="opp-row ${o.id===selectedOpportunityId?'selected':''}" data-row="${o.id}"><label class="row-check" title="Compare"><input type="checkbox" data-compare="${o.id}" ${compareSelection.has(o.id)?'checked':''}></label><button class="row-main" data-select="${o.id}" style="border:0;background:none;text-align:left;padding:0"><strong>${o.role}</strong><span>${o.company} · ${o.location}</span><small>${decisionText(o)}</small></button><div class="row-signal"><b>${o.trajectory}</b><span>${o.routeShort}</span></div><div class="row-updated"><b class="row-fresh">${o.fresh}</b>${o.updated}<br><button class="row-pin ${o.shortlisted?'active':''}" data-pin="${o.id}" title="${o.shortlisted?'Remove from shortlist':'Add to shortlist'}">${o.shortlisted?'★':'☆'}</button></div></div>`).join(''):'<div class="detail-section">Nothing here yet.</div>';
  document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedOpportunityId=b.dataset.select;log('opportunity_selected',{opportunity_id:selectedOpportunityId});renderOpportunityList();renderOpportunityDetail();if(matchMedia('(max-width:760px)').matches)document.getElementById('workbench').classList.add('mobile-detail-open')});
  document.querySelectorAll('[data-compare]').forEach(c=>c.onchange=()=>{c.checked?compareSelection.add(c.dataset.compare):compareSelection.delete(c.dataset.compare);renderCompareBar();log('compare_selection_changed',{opportunity_id:c.dataset.compare,selected:c.checked})});
  document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=e=>{e.stopPropagation();const o=byId(b.dataset.pin);o.shortlisted=!o.shortlisted;log('shortlist_pin_changed',{opportunity_id:o.id,shortlisted:o.shortlisted});renderOpportunityList();updateCounts()});
  updateCounts();renderCompareBar();
}
function assertionRow(x){return `<div class="assertion-row" data-assertion="${x.id||''}"><div class="assertion-label">${x.label}</div><div class="assertion-value"><strong>${x.value}</strong><span class="assertion-source">${x.source}${x.observed&&x.observed!=='—'?` · ${x.observed}`:''}${x.confidence?` · ${x.confidence} confidence`:''}</span></div><div class="assertion-status ${statusClass(x.status)}">${x.status}${x.impact?`<span class="impact">${x.impact} impact</span>`:''}</div></div>`}
function inlineAssertion([label,value,status,source]){return assertionRow({label,value,status,source})}
function sourceRows(rows){return rows.map(([name,date,used])=>`<div class="source-row"><span>${name}<small>${used}</small></span><span>${date}</span></div>`).join('')}
function routePrimary(o){if(!o.routes.length)return `<div class="route-block"><span>Current route</span><div class="route-main"><strong>No credible warm route found</strong><p>Direct application remains available.</p></div></div>`;const r=o.routes[0];return `<div class="route-block"><span>Best known route</span><div class="route-main"><strong>${r.name} · ${r.viability}</strong><p><b>Relationship fact:</b> ${r.fact}</p><p><b>Route assessment:</b> ${r.interpretation}</p></div></div>`}
function routeOptions(o){return o.routes.length?o.routes.map(r=>`<div class="route-opt"><div><strong>${r.name}</strong><span>${r.viability}</span></div><p>${r.fact}</p><p>${r.interpretation}</p></div>`).join(''):'<div class="route-opt"><div><strong>Direct route only</strong><span>Available</span></div><p>No relationship or recruiter route is currently supported by evidence.</p></div>'}
function detailActions(o){const s=dispositions[o.id];if(s==='pursuing')return `<button class="btn" data-action="note">Add note</button><button class="btn quiet danger" data-action="archive">Archive</button><button class="btn primary" data-action="workspace">Open workspace</button>`;if(s==='exploring')return `<button class="btn" data-action="save">Save for later</button><button class="btn quiet" data-action="dismiss">Close</button><button class="btn primary" data-action="pursue">Open pursuit workspace</button><span class="action-note">Creates a private working file for this opportunity. Nothing is sent, submitted, or shared.</span>`;if(s==='watching')return `<button class="btn quiet" data-action="dismiss">Close</button><button class="btn primary" data-action="research">${o.cta}</button>`;return `<button class="btn quiet" data-action="dismiss">Close</button><button class="btn" data-action="save">Save for later</button><button class="btn primary" data-action="research">${o.cta}</button>`}
function renderOpportunityDetail(){
  const o=byId(selectedOpportunityId);if(!o){document.getElementById('oppDetail').innerHTML='<div class="detail-section">Select an opportunity.</div>';return}
  const s=dispositions[o.id];const deep=researchOpen.has(o.id)||['exploring','pursuing'].includes(s);
  const supportedIds=o.confirmed?[...(o.confirmed||[]),...(o.estimates||[]),...(o.open||[])].filter(id=>a(id).status!=='Open'):[];
  const confirmed=o.confirmed?supportedIds.map(id=>assertionRow(a(id))).join(''):(o.inlineFacts||[]).map(inlineAssertion).join('');
  const openIds=o.open?(o.open||[]).filter(id=>a(id).status==='Open'):[];
  const open=o.open?(openIds.length?openIds.map(id=>assertionRow(a(id))).join(''):'<div class="brief-line"><span>Material unknowns</span><strong>None open in the current evidence snapshot</strong></div>'):(o.inlineOpen||[]).map(([label,value,impact])=>assertionRow({label,value,status:'Open',source:'No direct evidence',impact})).join('');
  const ev=evidence.map(e=>`<label class="ev-opt ${selectedEvidence.has(e.id)?'selected':''}" data-evidence="${e.id}"><input type="checkbox" ${selectedEvidence.has(e.id)?'checked':''}><span><strong>${e.title}</strong> · ${e.status}<small>${e.detail}</small></span></label>`).join('');
  document.getElementById('oppDetail').innerHTML=`<button class="text-btn mobile-detail-back" id="mobileBackList">← Shortlist</button><div class="insp-head"><div><div class="insp-role">${o.role}</div><div class="insp-company">${o.company} · ${o.location}</div></div><div class="insp-status"><b>${stateLabel[s]}</b><span>${o.shortlisted?'★ Shortlist':'Not shortlisted'}</span></div></div><p class="decision-line">${decisionText(o)}</p><section class="detail-section"><h3>What is supported</h3>${confirmed}</section><section class="detail-section"><h3>What could change the decision</h3>${open}</section><section class="detail-section"><h3>Career move</h3><div class="assertion-row"><div class="assertion-label">Trajectory</div><div class="assertion-value"><strong>${o.trajectory}</strong><span class="assertion-source">Compared with current scope and stated intent</span></div><div class="assertion-status estimate">Assessment</div></div></section><section class="detail-section"><h3>Route in</h3>${routePrimary(o)}</section><section class="detail-section"><h3>Source trail</h3>${sourceRows(o.sources)}</section><div class="actions">${detailActions(o)}</div><div id="researchBlock" class="research-block ${deep?'open':''}"><section class="detail-section"><h3>Research notes</h3><div class="research-grid"><div><strong>Supports</strong><ul class="research-list">${o.research.supports.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><strong>Still unresolved</strong><ul class="research-list">${o.research.unknowns.map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section><section class="detail-section"><h3>Alternative routes</h3>${routeOptions(o)}<div class="route-block"><span>External action</span><div class="route-main"><strong>None</strong><p>Research does not contact anyone.</p></div></div></section><section class="detail-section"><h3>Use your evidence</h3><button class="evidence-link" id="evidenceToggle">Choose experience for this mandate →</button><div id="evidencePicker" hidden><div class="evidence-picker">${ev}</div><button class="btn" id="bindEvidence">Use selected experience</button></div></section><div class="note-editor" id="noteEditor" hidden><textarea placeholder="Private note"></textarea><button class="btn" id="saveNote">Save note</button></div></div>`;
  bindDetail(o);
}
function bindDetail(o){
  document.getElementById('mobileBackList')?.addEventListener('click',()=>document.getElementById('workbench').classList.remove('mobile-detail-open'));
  document.querySelectorAll('#oppDetail [data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,o));
  document.getElementById('evidenceToggle')?.addEventListener('click',()=>{const p=document.getElementById('evidencePicker');p.hidden=!p.hidden;log('evidence_picker_toggled',{opportunity_id:o.id,open:!p.hidden})});
  document.querySelectorAll('.ev-opt').forEach(el=>el.onclick=ev=>{if(ev.target.tagName!=='INPUT')ev.preventDefault();const id=el.dataset.evidence;selectedEvidence.has(id)?selectedEvidence.delete(id):selectedEvidence.add(id);log('evidence_toggled',{opportunity_id:o.id,evidence_id:id,selected:selectedEvidence.has(id)});renderOpportunityDetail();document.getElementById('evidencePicker').hidden=false});
  document.getElementById('bindEvidence')?.addEventListener('click',()=>{if(!selectedEvidence.size){toast('Choose at least one experience');return}log('evidence_bound',{opportunity_id:o.id,evidence_ids:[...selectedEvidence],truth_status_changed:false,canonical_action:'ACT-MANDATE-EVIDENCE-BIND'});toast('Experience linked. Evidence status unchanged.')});
  document.getElementById('saveNote')?.addEventListener('click',()=>{const text=document.querySelector('#noteEditor textarea').value.trim();if(!text){toast('Write a note first');return}log('private_note_added',{opportunity_id:o.id,length:text.length});toast('Private note saved')});
}
function handleAction(action,o){
  if(action==='research'){dispositions[o.id]='exploring';researchOpen.add(o.id);log('disposition_changed',{opportunity_id:o.id,to:'exploring',canonical_action:'ACT-OPPORTUNITY-EXPLORE',surface_label:o.cta});renderOpportunityList();renderOpportunityDetail();return}
  if(action==='save'){dispositions[o.id]='watching';o.shortlisted=false;log('disposition_changed',{opportunity_id:o.id,to:'watching',canonical_action:'ACT-OPPORTUNITY-WATCH',surface_label:'Save for later'});toast('Saved for later');renderOpportunityList();renderOpportunityDetail();return}
  if(action==='dismiss'){dispositions[o.id]='passed';o.shortlisted=false;log('disposition_changed',{opportunity_id:o.id,to:'passed',canonical_action:'ACT-OPPORTUNITY-PASS',surface_label:'Close'});toast('Closed');renderOpportunityList();renderOpportunityDetail();return}
  if(action==='pursue'){dispositions[o.id]='pursuing';researchOpen.add(o.id);workspaceStage='precontact';applyStageAssertionSnapshot(workspaceStage);workspaceSection='brief';log('disposition_changed',{opportunity_id:o.id,to:'pursuing',canonical_action:'ACT-OPPORTUNITY-PURSUE',surface_label:'Open pursuit workspace',external_effect:false});showPursuitWorkspace(o.id);toast('Pursuit workspace opened — nothing sent');return}
  if(action==='workspace'){showPursuitWorkspace(o.id);return}
  if(action==='note'){const editor=document.getElementById('noteEditor');if(editor)editor.hidden=!editor.hidden;return}
  if(action==='archive'){dispositions[o.id]='closed';o.shortlisted=false;log('disposition_changed',{opportunity_id:o.id,to:'closed'});toast('Archived');renderOpportunityList();renderOpportunityDetail()}
}
function openOpportunity(id,reason='open_brief'){selectedOpportunityId=id;activeFilter='shortlist';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.filter==='shortlist'));showView('opportunities');renderOpportunityList();renderOpportunityDetail();if(matchMedia('(max-width:760px)').matches)document.getElementById('workbench').classList.add('mobile-detail-open');log('briefing_to_opportunity',{opportunity_id:id,reason})}

function renderCompareBar(){const bar=document.getElementById('compareBar');bar.hidden=compareSelection.size<2;document.getElementById('compareCount').textContent=`${compareSelection.size} selected`}
function biggestUnknown(o){if(o.open?.length){const id=o.open.find(x=>a(x).status==='Open');return id?a(id).label:'No material unknown at this stage'}if(o.inlineOpen?.length)return o.inlineOpen[0][0];return '—'}
function scopeSummary(o){if(o.confirmed?.length)return o.confirmed.map(id=>a(id).value).join(' · ');return o.inlineFacts?.[0]?.[1]||o.mandate||'—'}
function renderCompare(){const items=[...compareSelection].map(byId).filter(Boolean);const dimensions=[['Trajectory',o=>o.trajectory],['Scope / mandate',scopeSummary],['Route in',o=>o.routeShort],['Biggest unknown',biggestUnknown],['Source',o=>o.sources[0]?.[0]||'—'],['Candidate state',o=>stateLabel[dispositions[o.id]]]];document.getElementById('compareTable').innerHTML=`<table class="cmp-table"><thead><tr><th>Dimension</th>${items.map(o=>`<th>${o.role}<span class="cmp-sub">${o.company} · ${o.location}</span></th>`).join('')}</tr></thead><tbody>${dimensions.map(([name,get])=>`<tr><th>${name}</th>${items.map(o=>`<td>${get(o)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}

function showPursuitWorkspace(id){selectedOpportunityId=id;const o=byId(id);showView('pursuit');document.getElementById('pursuitTitle').textContent=o.role;document.getElementById('pursuitCompany').textContent=`${o.company} · ${o.location}`;document.getElementById('pursuitShortlistFlag').textContent=o.shortlisted?'★ Shortlist':'Not shortlisted';renderWorkspace();log('workspace_opened',{opportunity_id:id,stage:workspaceStage})}
function workspaceHeader(label,sub){return `<div class="workspace-section-head"><div class="eyebrow">${workspaceStages[workspaceStage].label}</div><h2>${label}</h2>${sub?`<p>${sub}</p>`:''}</div>`}
function nextMoveBlock(){const n=workspaceStages[workspaceStage].next;return `<div class="next-move"><div class="label">Next move</div><h3>${n.title}</h3><p>${n.why}</p><button class="btn primary" data-workspace-action="next">${n.cta}</button></div>`}
function workingBrief(o){const lines=o.id==='opp_apac_vpt_01'?[['Scope',a('apac_remit').value],['Reporting line',`${a('reports_to').value} · confirmed`],['Team',`${a('team_size').value} · estimate`],['Highest-impact unknown',biggestUnknown(o)],['Route',o.routeShort]]:[['Trajectory',o.trajectory],['Route',o.routeShort],['Open question',biggestUnknown(o)]];return lines.map(([k,v])=>`<div class="brief-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}
function readinessRows(){return workspaceStages[workspaceStage].ready.map(([k,v])=>`<div class="readiness-line"><span>${k}</span><span>${v}</span></div>`).join('')}
function timelineRows(rows=workspaceStages[workspaceStage].activity){return rows.map(([d,v])=>`<div class="timeline-row"><time>${d}</time><div>${v}</div></div>`).join('')}
function peopleContent(){const o=byId(selectedOpportunityId);let rows=`<div class="person-row"><div><strong>Sarah Tan</strong><small>Former colleague · worked together 2021</small></div><p>Relationship fact: worked together previously and Sarah is in Asteria's regional unit.<br><br>Route assessment: credible warm route; current relationship strength is not assumed.</p></div>`;if(['recruiter','selection','final','offer'].includes(workspaceStage))rows+=`<div class="person-row"><div><strong>Jane Liu</strong><small>Search consultant</small></div><p>Current search contact. Asked for an updated CV and is checking P&L ownership and compensation range.</p></div>`;if(['selection','final','offer'].includes(workspaceStage))rows+=`<div class="person-row"><div><strong>CEO</strong><small>Selection participant</small></div><p>Likely agenda: international expansion, operating leverage, and confidence that adjacent-industry experience transfers.</p></div>`;return `${workspaceHeader('People','Relationships, recruiter context, and selection stakeholders.')}${rows}`}
function positioningContent(){return `${workspaceHeader('Positioning','Only evidence permitted for this opportunity should flow into external materials.')}<div class="workspace-block"><h3>Mandate to evidence</h3><div class="brief-line"><span>International scale</span><strong>APAC engineering scale-up · source-backed</strong></div><div class="brief-line"><span>Transformation</span><strong>Post-merger platform consolidation · self-attested</strong></div><div class="brief-line"><span>Operating leverage</span><strong>Infrastructure economics · corroborated</strong></div></div><div class="workspace-block"><h3>Artifacts</h3>${readinessRows()}</div><div class="workspace-block"><h3>Guardrail</h3><p class="rail-note">Prepare is not share. Drafts remain private until the candidate explicitly approves an external action.</p></div>`}
function processContent(){const stages=processStages[workspaceStage];let extra='';if(workspaceStage==='selection')extra=`<div class="workspace-block"><h3>Next stakeholder</h3><div class="brief-line"><span>CEO</span><strong>26 Aug · 10:00</strong></div><div class="brief-line"><span>Known concern</span><strong>Direct fintech experience is adjacent, not exact</strong></div><div class="brief-line"><span>Evidence to use</span><strong>Three-country platform expansion</strong></div></div>`;if(workspaceStage==='final')extra=`<div class="workspace-block"><h3>Final round</h3><div class="brief-line"><span>Case</span><strong>15-minute operating thesis</strong></div><div class="brief-line"><span>References</span><strong>2 confirmed · 1 needed</strong></div></div>`;if(workspaceStage==='offer')extra=`<div class="workspace-block"><h3>Offer terms</h3><div class="offer-term"><span>Base</span><strong>SGD 310k</strong></div><div class="offer-term"><span>Bonus</span><strong>30% target</strong></div><div class="offer-term"><span>Equity</span><strong>4-year grant · details under review</strong></div><div class="offer-term"><span>Authority</span><strong>Strategy ownership confirmed in offer brief</strong></div></div>`;return `${workspaceHeader('Process','The workspace surfaces only the process work relevant to the current stage.')}<div class="workspace-block"><h3>Progress</h3>${stages.map(([name,desc,state])=>`<div class="process-stage ${state==='current'?'current':''}"><div class="stage-name">${name}</div><p>${desc}</p><div class="stage-state">${state}</div></div>`).join('')}</div>${extra}`}
function recordContent(){let rows=[['18 Aug','Company leadership announcement captured'],['20 Aug',`Recruiter call: reporting line = ${a('reports_to').value}`],['21 Aug','Role page snapshot captured'],...workspaceStages[workspaceStage].activity];return `${workspaceHeader('Record','Source trail, interactions, commitments, and debriefs in one chronology.')}<div class="workspace-block"><h3>Timeline</h3>${timelineRows(rows)}</div>${['recruiter','selection','final','offer'].includes(workspaceStage)?`<div class="workspace-block"><h3>Latest debrief</h3><div class="brief-line"><span>Observed</span><strong>Recruiter asked for updated CV</strong></div><div class="brief-line"><span>Proposed assertion</span><strong>P&L ownership appears material · requires review</strong></div><div class="brief-line"><span>Commitment</span><strong>Send CV after scope questions are answered</strong></div><p class="rail-note">Debrief extraction proposes observations/assertions. It does not silently rewrite known facts.</p></div>`:''}`}
function briefContent(o){return `${workspaceHeader('Working brief','One working file for this live opportunity.')}${nextMoveBlock()}<div class="workspace-split"><div><div class="workspace-block"><h3>Current picture</h3>${workingBrief(o)}</div><div class="workspace-block"><h3>Open questions</h3>${o.id==='opp_apac_vpt_01'?((o.open.filter(id=>a(id).status==='Open').map(id=>assertionRow(a(id))).join(''))||'<div class="brief-line"><span>Material unknowns</span><strong>None open in the current evidence snapshot</strong></div>'):'<div class="brief-line"><span>Highest impact</span><strong>'+biggestUnknown(o)+'</strong></div>'}</div></div><div><div class="workspace-block"><h3>Ready to use</h3>${readinessRows()}</div><div class="workspace-block"><h3>Recent activity</h3>${timelineRows()}</div></div></div>`}
function railContent(o){const n=workspaceStages[workspaceStage].next;return `<div class="rail-block"><h3>Stage</h3><div class="rail-big">${workspaceStages[workspaceStage].label}</div></div><div class="rail-block"><h3>Next move</h3><div class="rail-line">${n.title}</div></div><div class="rail-block"><h3>Decision state</h3><div class="rail-line"><span>Candidate</span><br>${stateLabel[dispositions[o.id]]}</div><div class="rail-line"><span>Search</span><br>Open</div><div class="rail-line"><span>Selection</span><br>${workspaceStage==='precontact'?'Not started':workspaceStage==='recruiter'?'Recruiter screen':workspaceStage==='selection'?'Interview':workspaceStage==='final'?'Final':workspaceStage==='offer'?'Offer':'Not started'}</div></div><div class="rail-block"><h3>Confidentiality</h3><div class="rail-note">Private opportunity workspace. No outreach, application, or sharing occurs automatically.</div></div>`}
function renderWorkspace(){const o=byId(selectedOpportunityId);document.getElementById('pursuitStageEyebrow').textContent=workspaceStages[workspaceStage].label.toUpperCase();document.querySelectorAll('.workspace-nav-item').forEach(b=>b.classList.toggle('active',b.dataset.workspaceSection===workspaceSection));let html='';if(workspaceSection==='brief')html=briefContent(o);if(workspaceSection==='people')html=peopleContent();if(workspaceSection==='positioning')html=positioningContent();if(workspaceSection==='process')html=processContent();if(workspaceSection==='record')html=recordContent();document.getElementById('workspaceContent').innerHTML=html;document.getElementById('workspaceRail').innerHTML=railContent(o);document.querySelector('[data-workspace-action="next"]')?.addEventListener('click',()=>{log('workspace_next_action_opened',{opportunity_id:o.id,stage:workspaceStage,label:workspaceStages[workspaceStage].next.cta});toast(`${workspaceStages[workspaceStage].next.cta} opened — no external action`)})}

function renderCareer(){document.getElementById('evidenceLibrary').innerHTML=evidence.map(e=>`<div class="evidence-row"><strong>${e.title}</strong><p>${e.detail}</p><span>${e.status}</span></div>`).join('')}
function renderEvents(){const el=document.getElementById('eventLog');if(!el)return;el.innerHTML=session.events.slice().reverse().map(e=>`<div class="event"><b>${e.t_ms}ms · ${e.type}</b><br>${Object.entries(e).filter(([k])=>!['t_ms','type'].includes(k)).map(([k,v])=>`${k}: ${JSON.stringify(v)}`).join('<br>')}</div>`).join('')}

// opportunity filters / comparison
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{activeFilter=t.dataset.filter;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));document.getElementById('workbench').classList.remove('mobile-detail-open');renderOpportunityList();renderOpportunityDetail();log('opportunity_filter_changed',{filter:activeFilter})});
document.getElementById('compareGo').onclick=()=>{renderCompare();document.getElementById('workbench').hidden=true;document.querySelector('.tabs').hidden=true;document.getElementById('compareView').hidden=false;document.getElementById('compareBar').hidden=true;log('comparison_opened',{opportunity_ids:[...compareSelection]})};
document.getElementById('cmpBack').onclick=()=>{document.getElementById('compareView').hidden=true;document.getElementById('workbench').hidden=false;document.querySelector('.tabs').hidden=false;renderCompareBar()};
document.getElementById('compareClear').onclick=()=>{compareSelection.clear();renderOpportunityList()};

// workspace navigation
document.querySelectorAll('.workspace-nav-item').forEach(b=>b.onclick=()=>{workspaceSection=b.dataset.workspaceSection;renderWorkspace();log('workspace_section_changed',{section:workspaceSection,stage:workspaceStage})});
document.getElementById('backToOpportunities').onclick=()=>{showView('opportunities');renderOpportunityList();renderOpportunityDetail()};

// primary navigation
document.querySelectorAll('.nav-item').forEach(n=>n.onclick=()=>{showView(n.dataset.view);if(n.dataset.view==='opportunities'){renderOpportunityList();renderOpportunityDetail()}if(n.dataset.view==='career')renderCareer();log('nav',{view:n.dataset.view})});

// researcher controls
const params=new URLSearchParams(location.search);const researchMode=params.get('research')==='1';const researchToggle=document.getElementById('researchToggle'),researchPanel=document.getElementById('researchPanel');if(researchMode){researchToggle.hidden=false;researchToggle.onclick=()=>{const open=!researchPanel.classList.contains('open');researchPanel.classList.toggle('open',open);researchPanel.setAttribute('aria-hidden',String(!open))}}document.getElementById('closeResearch').onclick=()=>{researchPanel.classList.remove('open');researchPanel.setAttribute('aria-hidden','true')};document.querySelectorAll('[data-demo-stage]').forEach(b=>b.onclick=()=>{workspaceStage=b.dataset.demoStage;applyStageAssertionSnapshot(workspaceStage);dispositions[selectedOpportunityId]='pursuing';workspaceSection='brief';showPursuitWorkspace(selectedOpportunityId);log('research_scenario_stage_changed',{stage:workspaceStage})});document.getElementById('copySession').onclick=async()=>{await navigator.clipboard?.writeText(JSON.stringify(session,null,2));toast('Session JSON copied')};
window.__scopeCareerSetWorkspaceStage=stage=>{if(workspaceStages[stage]){workspaceStage=stage;applyStageAssertionSnapshot(workspaceStage);dispositions[selectedOpportunityId]='pursuing';workspaceSection='brief';showPursuitWorkspace(selectedOpportunityId);return true}return false};
window.__scopeCareerAssertions=assertions;

renderBriefing();renderOpportunityList();renderOpportunityDetail();renderCareer();
const requested=params.get('view');if(['briefing','opportunities','career'].includes(requested))showView(requested);if(requested==='pursuit'){dispositions[selectedOpportunityId]='pursuing';showPursuitWorkspace(selectedOpportunityId)}
const requestedStage=params.get('stage');if(requestedStage&&workspaceStages[requestedStage]){workspaceStage=requestedStage;applyStageAssertionSnapshot(workspaceStage);dispositions[selectedOpportunityId]='pursuing';showPursuitWorkspace(selectedOpportunityId)}
log('prototype_loaded',{version:'v3',viewport:`${innerWidth}x${innerHeight}`});
